INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Einrichtung IT-Arbeitsplätze > IT-Sicherheit > Risikoanalyse Arbeitsplatz
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss eine Risikoanalyse für IT-Arbeitsplätze immer vor der Inbetriebnahme durchgeführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Frühzeitige Identifikation von Risiken ist gesetzlich und praktisch erforderlich"}, {"text": "Nein", "correct": false, "because": "Vorab-Analyse ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Sicherheitsrisiken am Arbeitsplatz ohne Dokumentation bewertet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation ist für Nachvollziehbarkeit und Compliance nötig"}, {"text": "Ja", "correct": false, "because": "Dokumentation ist Best Practice"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Risikoanalyse am IT-Arbeitsplatz nur auf technische Risiken beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische und menschliche Faktoren werden berücksichtigt"}, {"text": "Ja", "correct": false, "because": "Umfassende Analyse erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Sicherheitslücken durch eine Risikoanalyse vollständig eliminiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken können reduziert, aber nicht vollständig beseitigt werden"}, {"text": "Ja", "correct": false, "because": "Restrisiken bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind gesetzliche Vorgaben wie die DSGVO bei der Risikoanalyse für IT-Arbeitsplätze zu beachten?', 2, '[{"text": "Ja", "correct": true, "because": "Datenschutz und Sicherheit sind gesetzlich vorgeschrieben"}, {"text": "Nein", "correct": false, "because": "Gesetze sind maßgeblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Risikoanalyse für IT-Arbeitsplätze am wichtigsten?', 3, '[{"text": "Risikoidentifikation", "correct": true, "because": "Grundlage für alle weiteren Maßnahmen"}, {"text": "Kostenberechnung", "correct": false, "because": "Sekundär"}, {"text": "Farbauswahl", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko wird bei einer IT-Arbeitsplatz-Analyse häufig identifiziert?', 2, '[{"text": "Datenverlust", "correct": true, "because": "Häufig durch technische oder menschliche Fehler"}, {"text": "Geräuschbelastung", "correct": false, "because": "Arbeitsschutz, nicht IT-Sicherheit"}, {"text": "Stromausfall", "correct": false, "because": "Externer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Risikoanalyse am IT-Arbeitsplatz?', 2, '[{"text": "Risikomatrix", "correct": true, "because": "Bewertet Risiken nach Eintrittswahrscheinlichkeit und Schaden"}, {"text": "Textverarbeitung", "correct": false, "because": "Nicht spezifisch"}, {"text": "Schraubendreher", "correct": false, "because": "Hardware-Werkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage ist für die IT-Sicherheits-Risikoanalyse relevant?', 3, '[{"text": "DSGVO", "correct": true, "because": "Regelt Datenschutz und Sicherheit"}, {"text": "Arbeitsschutzgesetz", "correct": false, "because": "Für physische Sicherheit"}, {"text": "Kreislaufwirtschaftsgesetz", "correct": false, "because": "Für Recycling"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel einer Risikoanalyse am IT-Arbeitsplatz?', 2, '[{"text": "Risikominimierung", "correct": true, "because": "Schützt Daten und Systeme"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}, {"text": "Schnellere Installation", "correct": false, "because": "Nicht primär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Risikoanalyse für IT-Arbeitsplätze?', 4, '[{"text": "Risiken identifizieren", "correct": true, "because": "Erster Schritt"}, {"text": "Risiken bewerten", "correct": true, "because": "Einschätzung der Schwere"}, {"text": "Maßnahmen planen", "correct": true, "because": "Reduziert Risiken"}, {"text": "Farben auswählen", "correct": false, "because": "Ästhetisch, nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können an IT-Arbeitsplätzen auftreten?', 3, '[{"text": "Datenverlust", "correct": true, "because": "Durch Hardwarefehler oder Angriffe"}, {"text": "Cyberangriffe", "correct": true, "because": "Bedrohen Sicherheit"}, {"text": "Unbefugter Zugriff", "correct": true, "because": "Gefährdet Daten"}, {"text": "Hohe Temperatur", "correct": false, "because": "Arbeitsschutz, nicht IT-Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Risikoanalyse am IT-Arbeitsplatz?', 3, '[{"text": "Risikomatrix", "correct": true, "because": "Visualisiert Risiken"}, {"text": "Checklisten", "correct": true, "because": "Systematische Prüfung"}, {"text": "Sicherheitsaudit", "correct": true, "because": "Umfassende Bewertung"}, {"text": "Farbanalyse", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren werden bei der Risikoanalyse bewertet?', 4, '[{"text": "Eintrittswahrscheinlichkeit", "correct": true, "because": "Wie wahrscheinlich ist das Risiko"}, {"text": "Schadensausmaß", "correct": true, "because": "Auswirkung des Risikos"}, {"text": "Schutzmaßnahmen", "correct": true, "because": "Vorhandene Sicherungen"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Risikoanalyse am IT-Arbeitsplatz?', 3, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Schützt Systeme"}, {"text": "Datenschutz", "correct": true, "because": "Sichert sensible Daten"}, {"text": "Gesetzeskonformität", "correct": true, "because": "Erfüllt Vorschriften"}, {"text": "Schnellere Installation", "correct": false, "because": "Nicht primär"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Risikoanalyse identifiziert potenzielle Sicherheitslücken. b) Sie kann ohne Dokumentation durchgeführt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identifikation ja, Dokumentation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO fordert eine Risikoanalyse für Datenschutz. b) Technische Risiken sind der einzige Fokus der Analyse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO ja, auch organisatorische Risiken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Risikomatrix hilft bei der Risikobewertung. b) Risiken können durch die Analyse vollständig beseitigt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Matrix ja, Beseitigung nicht möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Datenverlust ist ein typisches Risiko am IT-Arbeitsplatz. b) Die Risikoanalyse ist nach der Inbetriebnahme unnötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenverlust ja, Analyse vorab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sicherheitsmaßnahmen werden durch die Risikoanalyse geplant. b) Die Analyse betrifft nur große Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maßnahmen ja, für alle Unternehmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

